 const collectionTilesStyle='<style>.sdl-collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.sdl-collection-tile{border:1px solid #d1dce7;background:white;border-radius:15px;overflow:hidden;box-shadow:0 8px 22px #152a4514}.sdl-collection-image{height:145px;background:#0c2132}.sdl-collection-image img{width:100%;height:100%;object-fit:cover}.sdl-collection-tile>div:last-child{padding:19px}.sdl-collection-tile small,.sdl-category-tile small{color:#96703a;font-weight:800;letter-spacing:.1em;font-size:11px}.sdl-collection-tile h3{font-family:Georgia,serif;color:#12273f;font-size:25px;margin:8px 0}.sdl-collection-tile p{color:#62748a;font-size:13px}.sdl-col-open,.sdl-col-back,.sdl-cat-back,.sdl-cat-open{cursor:pointer;border:1px solid #a58550;border-radius:9px;padding:11px 16px;background:#102a40;color:#f1d59d;font-weight:800}.sdl-col-screen[hidden],.sdl-category-content[hidden],.sdl-category-grid[hidden],.sdl-collection-grid[hidden]{display:none!important}.sdl-col-screen-head{margin-bottom:20px}.sdl-col-screen-head h3{font:700 27px Georgia,serif;color:#102740}.sdl-category-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.sdl-category-tile{background:#f5f8fb;border:1px solid #cfdae4;border-radius:12px;min-width:0}.sdl-cat-open{width:100%;min-height:130px;display:flex;flex-direction:column;align-items:flex-start;gap:12px;justify-content:space-between;text-align:left;background:#f5f8fb;color:#102b44;border:0}.sdl-cat-open strong{font:700 20px Georgia,serif}.sdl-cat-open span{font-size:12px;color:#987138}.sdl-category-content{padding:15px}.sdl-category-content h4{font:700 24px Georgia,serif;color:#132e47}@media(max-width:900px){.sdl-collection-grid,.sdl-category-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:590px){.sdl-collection-grid,.sdl-category-grid{grid-template-columns:1fr}}</style>';
